//! Provider-backed folders, moves and rules. IMAP rules run locally while open.
use crate::{Account,App,Result,mail_store::MailStore};
use base64::{engine::general_purpose::{STANDARD,URL_SAFE_NO_PAD},Engine};
use imap::types::NameAttribute;
use serde_json::{json,Value};
use std::{io::{Read,Write},net::{TcpStream,ToSocketAddrs},sync::Arc,time::{Duration,Instant}};

const GM:&str="https://gmail.googleapis.com/gmail/v1/users/me";
const MS:&str="https://graph.microsoft.com/v1.0/me";
fn name(value:&str)->Result<String>{let value=value.trim();if value.is_empty()||value.len()>255||value.chars().any(char::is_control){return Err("Enter a folder or rule name up to 255 characters.".into())}Ok(value.into())}
fn raw_id(value:&str)->Result<&str>{let value=value.strip_prefix("custom:").unwrap_or(value);if value.is_empty()||value.len()>8192||value.chars().any(char::is_control){return Err("Invalid folder identifier.".into())}Ok(value)}
fn exchange_credentials(account:&Account)->Result<crate::exchange::Credentials>{crate::mail_credentials::load(&format!("{}:exchange",account.id))}

struct Bounded{stream:native_tls::TlsStream<TcpStream>,remaining:usize,deadline:Instant}
impl Read for Bounded{fn read(&mut self,buf:&mut[u8])->std::io::Result<usize>{if self.remaining==0||Instant::now()>self.deadline{return Err(std::io::Error::other("IMAP folder response exceeded the limit"))}let len=buf.len().min(self.remaining);let n=self.stream.read(&mut buf[..len])?;self.remaining-=n;Ok(n)}}
impl Write for Bounded{fn write(&mut self,buf:&[u8])->std::io::Result<usize>{self.stream.write(buf)}fn flush(&mut self)->std::io::Result<()>{self.stream.flush()}}
type Session=imap::Session<Bounded>;
fn line(stream:&mut TcpStream)->Result<Vec<u8>>{let mut out=vec![];let mut byte=[0];while out.len()<16384{stream.read_exact(&mut byte).map_err(|_|"The IMAP server timed out or closed the connection.")?;out.push(byte[0]);if out.ends_with(b"\r\n"){return Ok(out)}}Err("The IMAP server returned an oversized response.".into())}
fn imap(account:&Account)->Result<Session>{let settings=account.manual.as_ref().filter(|s|s.protocol=="imap").ok_or("Folder management requires IMAP, Google, Microsoft or EWS.")?;let credentials=crate::manual_credentials(account)?;crate::manual_mail::validate(settings,&credentials)?;let server=settings.incoming.as_ref().ok_or("Incoming server missing")?;let host=server.host.trim_matches(['[',']']);let mut socket=None;for address in(host,server.port).to_socket_addrs().map_err(|_|"Could not resolve the IMAP server.")?.take(4){if let Ok(stream)=TcpStream::connect_timeout(&address,Duration::from_secs(8)){socket=Some(stream);break;}}let mut socket=socket.ok_or("Could not reach the IMAP server.")?;socket.set_read_timeout(Some(Duration::from_secs(15))).map_err(crate::err)?;socket.set_write_timeout(Some(Duration::from_secs(15))).map_err(crate::err)?;let starttls=server.security=="starttls";if starttls{if !line(&mut socket)?.starts_with(b"* OK"){return Err("The server did not offer an IMAP greeting.".into())}socket.write_all(b"yasF STARTTLS\r\n").map_err(|_|"Could not request IMAP encryption.")?;let mut accepted=false;for _ in 0..100{let response=line(&mut socket)?;if response.starts_with(b"yasF "){accepted=response.starts_with(b"yasF OK");break;}}if !accepted{return Err("The IMAP server rejected required STARTTLS. No password was sent.".into())}}let connector=native_tls::TlsConnector::builder().min_protocol_version(Some(native_tls::Protocol::Tlsv12)).build().map_err(|_|"Could not initialize TLS.")?;let stream=connector.connect(host,socket).map_err(|_|"IMAP TLS certificate verification failed.")?;let mut client=imap::Client::new(Bounded{stream,remaining:8_000_000,deadline:Instant::now()+Duration::from_secs(60)});if !starttls{client.read_greeting().map_err(|_|"The server did not offer an IMAP greeting.")?;}client.login(&server.username,&credentials.incoming_password).map_err(|_|"IMAP authentication failed.".into())}
fn imap_folder(id:&str)->Result<String>{let raw=id.strip_prefix("custom:").ok_or("Choose a custom IMAP folder.")?;let folder=String::from_utf8(URL_SAFE_NO_PAD.decode(raw).map_err(|_|"Invalid IMAP folder.")?).map_err(|_|"Invalid IMAP folder.")?;if folder.is_empty()||folder.len()>1000||folder.chars().any(char::is_control){return Err("Invalid IMAP folder.".into())}Ok(folder)}
fn imap_id(name:&str)->String{format!("custom:{}",URL_SAFE_NO_PAD.encode(name))}
fn utf7_encode(value:&str)->String{let mut out=String::new();let mut pending=String::new();fn flush(pending:&mut String,out:&mut String){if !pending.is_empty(){let bytes=pending.encode_utf16().flat_map(u16::to_be_bytes).collect::<Vec<_>>();out.push('&');out.push_str(STANDARD.encode(bytes).trim_end_matches('=').replace('/',",").as_str());out.push('-');pending.clear();}}for c in value.chars(){if c.is_ascii()&&!c.is_control(){flush(&mut pending,&mut out);if c=='&'{out.push_str("&-")}else{out.push(c)}}else{pending.push(c)}}flush(&mut pending,&mut out);out}
fn utf7_decode(value:&str)->String{let mut out=String::new();let mut rest=value;while let Some(at)=rest.find('&'){out.push_str(&rest[..at]);rest=&rest[at+1..];let Some(end)=rest.find('-')else{out.push('&');out.push_str(rest);return out};let encoded=&rest[..end];if encoded.is_empty(){out.push('&')}else{let mut encoded=encoded.replace(',',"/");while encoded.len()%4!=0{encoded.push('=')}if let Ok(bytes)=STANDARD.decode(encoded){let units=bytes.chunks_exact(2).map(|b|u16::from_be_bytes([b[0],b[1]])).collect::<Vec<_>>();out.push_str(&String::from_utf16_lossy(&units));}else{out.push('&');out.push_str(&rest[..=end]);}}rest=&rest[end+1..];}out.push_str(rest);out}

pub async fn folders(state:&App,account:&Account)->Result<Value>{
    if let Some(settings)=&account.exchange{return crate::exchange::folders(settings.clone(),exchange_credentials(account)?).await}
    if account.provider=="imap"{let account=account.clone();return tokio::task::spawn_blocking(move||{let mut session=imap(&account)?;let rows=session.list(None,Some("*")).map_err(|_|"Could not list IMAP folders.")?;let output=rows.iter().filter(|row|!row.attributes().contains(&NameAttribute::NoSelect)).take(1000).map(|row|{let system=row.name().eq_ignore_ascii_case("INBOX")||row.attributes().iter().any(|a|matches!(a,NameAttribute::Custom(v)if["\\Sent","\\Drafts","\\Trash","\\Junk","\\Archive"].iter().any(|name|v.eq_ignore_ascii_case(name))));json!({"id":imap_id(row.name()),"name":utf7_decode(row.name()),"system":system,"canRename":!system,"canDelete":!system})}).collect::<Vec<_>>();let _=session.logout();Ok(json!(output))}).await.map_err(|_|"The folder task could not finish.")?}
    if account.provider=="gmail"{let page=state.api(account,"GET",&format!("{GM}/labels"),Value::Null).await?;return Ok(json!(page["labels"].as_array().unwrap_or(&vec![]).iter().map(|row|json!({"id":format!("custom:{}",row["id"].as_str().unwrap_or("")),"name":row["name"],"system":row["type"]=="system","canRename":row["type"]=="user","canDelete":row["type"]=="user"})).collect::<Vec<_>>()))}
    if account.provider=="outlook"{let mut rows=vec![];let mut next=Some(format!("{MS}/mailFolders?$top=100&includeHiddenFolders=false"));for _ in 0..20{let Some(url)=next else{break};if !url.starts_with(&format!("{MS}/mailFolders")){return Err("The provider returned an invalid folder continuation.".into())}let page=state.api(account,"GET",&url,Value::Null).await?;for row in page["value"].as_array().unwrap_or(&vec![]){rows.push(json!({"id":format!("custom:{}",row["id"].as_str().unwrap_or("")),"name":row["displayName"],"total":row["totalItemCount"],"unread":row["unreadItemCount"],"canRename":true,"canDelete":true,"system":false,"hasChildren":row["childFolderCount"].as_u64().unwrap_or(0)>0}));}next=page["@odata.nextLink"].as_str().map(str::to_owned);}return Ok(json!(rows))}
    Err("Folders are not provided by POP3 or SMTP-only accounts.".into())
}
pub async fn save_folder(state:&App,account:&Account,id:Option<&str>,folder_name:&str,parent:Option<&str>,delete:bool)->Result<Value>{
    let display=if delete{String::new()}else{name(folder_name)?};
    if let Some(settings)=&account.exchange{return crate::exchange::folder_save(settings.clone(),exchange_credentials(account)?,json!({"id":id.unwrap_or(""),"name":display,"parent":parent.unwrap_or("")}),delete).await}
    if account.provider=="imap"{let account=account.clone();let id=id.map(str::to_owned);let parent=parent.map(str::to_owned);return tokio::task::spawn_blocking(move||{let mut session=imap(&account)?;let old=id.as_deref().map(imap_folder).transpose()?;if old.as_deref().is_some_and(|v|v.eq_ignore_ascii_case("INBOX")){return Err("The IMAP inbox cannot be renamed or removed.".into())}if display.contains(['/','\\']){return Err("Use the parent folder control instead of separators in a folder name.".into())}let mut target=utf7_encode(&display);if let Some(parent)=parent{let parent=imap_folder(&parent)?;let delimiter=session.list(None,Some(&parent)).ok().and_then(|names|names.first().and_then(|name|name.delimiter().map(str::to_owned))).unwrap_or_else(||"/".into());target=format!("{parent}{delimiter}{target}");}if delete{session.delete(old.as_deref().ok_or("Choose a folder to delete.")?).map_err(|_|"The server could not delete this folder. It may contain messages or protected folders.")?;}else if let Some(old)=old{session.rename(old,&target).map_err(|_|"The server could not rename this folder.")?;}else{session.create(&target).map_err(|_|"The server could not create this folder.")?;}let _=session.logout();Ok(json!({"ok":true,"id":imap_id(&target),"name":display}))}).await.map_err(|_|"The folder task could not finish.")?}
    if account.provider=="gmail"{
        if let Some(id)=id{let id=raw_id(id)?;let existing=state.api(account,"GET",&format!("{GM}/labels/{}",crate::segment(id)),Value::Null).await?;if existing["type"]!="user"{return Err("Built-in Gmail labels cannot be renamed or removed.".into())}if delete{return state.api(account,"DELETE",&format!("{GM}/labels/{}",crate::segment(id)),Value::Null).await}return state.api(account,"PATCH",&format!("{GM}/labels/{}",crate::segment(id)),json!({"name":display})).await}
        let mut full=display;if let Some(parent)=parent{let row=state.api(account,"GET",&format!("{GM}/labels/{}",crate::segment(raw_id(parent)?)),Value::Null).await?;full=format!("{}/{}",row["name"].as_str().unwrap_or(""),full);}
        let row=state.api(account,"POST",&format!("{GM}/labels"),json!({"name":full,"labelListVisibility":"labelShow","messageListVisibility":"show"})).await?;return Ok(json!({"id":format!("custom:{}",row["id"].as_str().unwrap_or("")),"name":row["name"]}))
    }
    if account.provider=="outlook"{
        if let Some(id)=id{let id=raw_id(id)?;for system in ["inbox","sentitems","drafts","deleteditems","junkemail","archive"]{let builtin=state.api(account,"GET",&format!("{MS}/mailFolders/{system}?$select=id"),Value::Null).await?;if builtin["id"]==id{return Err("Built-in Microsoft folders cannot be renamed or removed here.".into())}}
            return state.api(account,if delete{"DELETE"}else{"PATCH"},&format!("{MS}/mailFolders/{}",crate::segment(id)),if delete{Value::Null}else{json!({"displayName":display})}).await;
        }
        let base=if let Some(parent)=parent{format!("{MS}/mailFolders/{}/childFolders",crate::segment(raw_id(parent)?))}else{format!("{MS}/mailFolders")};let row=state.api(account,"POST",&base,json!({"displayName":display})).await?;return Ok(json!({"id":format!("custom:{}",row["id"].as_str().unwrap_or("")),"name":row["displayName"]}));
    }
    Err("Folder management is not supported by this account.".into())
}

pub async fn move_message(state:&App,account:&Account,id:&str,folder:&str)->Result<Value>{
    if let Some(settings)=&account.exchange{return crate::exchange::move_message(settings.clone(),exchange_credentials(account)?,id.into(),folder.into(),false).await}
    if account.provider=="gmail"{return state.api(account,"POST",&format!("{GM}/messages/{}/modify",crate::segment(id)),json!({"addLabelIds":[raw_id(folder)?],"removeLabelIds":["INBOX"]})).await}
    if account.provider=="outlook"{return state.api(account,"POST",&format!("{MS}/messages/{}/move",crate::segment(id)),json!({"destinationId":raw_id(folder)?})).await}
    if account.provider=="imap"{
        let encoded=id.strip_prefix("imap:").ok_or("Invalid IMAP message identifier.")?;if encoded.len()>3000{return Err("Invalid IMAP message identifier.".into())}let value:Value=serde_json::from_slice(&URL_SAFE_NO_PAD.decode(encoded).map_err(|_|"Invalid IMAP message identifier.")?).map_err(|_|"Invalid IMAP message identifier.")?;
        let source=value["mailbox"].as_str().ok_or("Invalid IMAP message folder.")?.to_string();let uid=value["uid"].as_u64().filter(|n|*n>0&&*n<=u32::MAX as u64).ok_or("Invalid IMAP message UID.")? as u32;let validity=value["validity"].as_u64().ok_or("Invalid IMAP UIDVALIDITY.")?;let target=imap_folder(folder)?;let account=account.clone();return tokio::task::spawn_blocking(move||{let mut session=imap(&account)?;let selected=session.select(&source).map_err(|_|"The source folder could not be opened.")?;if selected.uid_validity.map(u64::from)!=Some(validity){return Err("This IMAP folder changed. Refresh before moving messages.".into())}let caps=session.capabilities().map_err(|_|"Could not check IMAP MOVE support.")?;if !caps.has_str("MOVE"){return Err("This server does not support safe UID MOVE. Yas Mail will not expunge unrelated messages.".into())}session.uid_mv(uid.to_string(),&target).map_err(|_|"The server could not move this message.")?;let _=session.logout();Ok(json!({"ok":true}))}).await.map_err(|_|"The IMAP move could not finish.")?;
    }
    Err("POP3 and SMTP-only accounts do not support server message moves.".into())
}

fn field(rule:&Value,group:&str,key:&str)->String{rule[group][key].as_str().unwrap_or("").trim().to_string()}
fn validate_rule(rule:&Value)->Result<()>{name(rule["name"].as_str().unwrap_or(""))?;if rule.to_string().len()>20_000{return Err("This rule is too large.".into())}for key in ["from","to","subject","contains"]{let value=field(rule,"conditions",key);if value.len()>500||value.chars().any(char::is_control){return Err("Rule conditions must be at most 500 characters without control characters.".into())}}let conditions=&rule["conditions"];if ["from","to","subject","contains"].iter().all(|k|conditions[k].as_str().unwrap_or("").trim().is_empty())&&!conditions["hasAttachment"].as_bool().unwrap_or(false){return Err("Add at least one rule condition.".into())}let actions=&rule["actions"];if actions["folder"].as_str().unwrap_or("").is_empty()&&!["markRead","star","trash"].iter().any(|k|actions[k].as_bool().unwrap_or(false)){return Err("Choose at least one rule action.".into())}Ok(())}
pub fn rule_matches(rule:&Value,message:&Value)->bool{for(key,source)in[("from","from"),("to","to"),("subject","subject"),("contains","body")]{let needle=field(rule,"conditions",key).to_lowercase();if !needle.is_empty()&&!message[source].as_str().unwrap_or("").to_lowercase().contains(&needle){return false}}!rule["conditions"]["hasAttachment"].as_bool().unwrap_or(false)||message["attachments"].as_array().is_some_and(|files|!files.is_empty())}
pub async fn apply_rule(state:&App,account:&Account,rule:&Value,id:&str)->Result<()>{for(action,key)in[("read","markRead"),("star","star")]{if rule["actions"][key].as_bool().unwrap_or(false){crate::perform_mail_action(state,account,id.into(),action.into()).await?;}}if rule["actions"]["trash"].as_bool().unwrap_or(false){crate::perform_mail_action(state,account,id.into(),"trash".into()).await?;}else if let Some(folder)=rule["actions"]["folder"].as_str().filter(|s|!s.is_empty()){move_message(state,account,id,folder).await?;}Ok(())}
fn google_rule(rule:&Value)->Result<Value>{validate_rule(rule)?;if !rule["enabled"].as_bool().unwrap_or(true){return Err("Gmail filters cannot be disabled. Delete the filter instead.".into())}let c=&rule["conditions"];let a=&rule["actions"];let mut criteria=json!({});for key in ["from","to","subject"]{if let Some(value)=c[key].as_str().filter(|s|!s.trim().is_empty()){criteria[key]=json!(value);}}if let Some(value)=c["contains"].as_str().filter(|s|!s.trim().is_empty()){criteria["query"]=json!(format!("\"{}\"",value.replace('"',"\\\"")));}if c["hasAttachment"].as_bool().unwrap_or(false){criteria["hasAttachment"]=json!(true)}let mut add=vec![];let mut remove=vec![];if let Some(folder)=a["folder"].as_str().filter(|s|!s.is_empty()){add.push(raw_id(folder)?.to_string());remove.push("INBOX");}if a["trash"].as_bool().unwrap_or(false){add.push("TRASH".into());remove.push("INBOX");}if a["star"].as_bool().unwrap_or(false){add.push("STARRED".into())}if a["markRead"].as_bool().unwrap_or(false){remove.push("UNREAD");}Ok(json!({"criteria":criteria,"action":{"addLabelIds":add,"removeLabelIds":remove}}))}
fn microsoft_rule(rule:&Value)->Result<Value>{validate_rule(rule)?;if rule["actions"]["star"].as_bool().unwrap_or(false){return Err("Microsoft inbox rules do not support this star action.".into())}let mut conditions=json!({});for(field,predicate)in[("from","senderContains"),("to","recipientContains"),("subject","subjectContains"),("contains","bodyContains")]{let value=field_value(rule,field);if !value.is_empty(){conditions[predicate]=json!([value]);}}if rule["conditions"]["hasAttachment"].as_bool().unwrap_or(false){conditions["hasAttachments"]=json!(true)}let mut actions=json!({"stopProcessingRules":false});if rule["actions"]["markRead"].as_bool().unwrap_or(false){actions["markAsRead"]=json!(true)}if rule["actions"]["trash"].as_bool().unwrap_or(false){actions["delete"]=json!(true)}else if let Some(folder)=rule["actions"]["folder"].as_str().filter(|s|!s.is_empty()){actions["moveToFolder"]=json!(raw_id(folder)?)}Ok(json!({"displayName":rule["name"],"sequence":1,"isEnabled":rule["enabled"].as_bool().unwrap_or(true),"conditions":conditions,"actions":actions}))}
fn field_value(rule:&Value,key:&str)->String{field(rule,"conditions",key)}

#[tauri::command]
pub async fn mail_folder_list(window:tauri::WebviewWindow,state:tauri::State<'_,Arc<App>>,account:String)->Result<Value>{crate::windows::check_owner(&state,window.label(),&account)?;let a=state.account(&account).await?;folders(&state,&a).await}
#[tauri::command]
pub async fn mail_folder_save(window:tauri::WebviewWindow,state:tauri::State<'_,Arc<App>>,account:String,id:Option<String>,name:String,parent:Option<String>)->Result<Value>{crate::windows::check_owner(&state,window.label(),&account)?;let a=state.account(&account).await?;save_folder(&state,&a,id.as_deref(),&name,parent.as_deref(),false).await}
#[tauri::command]
pub async fn mail_folder_delete(window:tauri::WebviewWindow,state:tauri::State<'_,Arc<App>>,account:String,id:String)->Result<Value>{crate::windows::check_owner(&state,window.label(),&account)?;let a=state.account(&account).await?;save_folder(&state,&a,Some(&id),"",None,true).await}

#[tauri::command]
pub async fn mail_rule_list(window:tauri::WebviewWindow,state:tauri::State<'_,Arc<App>>,store:tauri::State<'_,Arc<MailStore>>,account:String)->Result<Value>{crate::windows::check_owner(&state,window.label(),&account)?;let a=state.account(&account).await?;if let Some(settings)=&a.exchange{return crate::exchange::rules(settings.clone(),exchange_credentials(&a)?).await}if a.provider=="imap"{return Ok(json!({"scope":"local","items":store.local_rules(&account)?,"notice":"These rules run in Yas Mail on newly synchronized messages while the app is open."}))}if a.provider=="gmail"{let v=state.api(&a,"GET",&format!("{GM}/settings/filters"),Value::Null).await?;let items=v["filter"].as_array().unwrap_or(&vec![]).iter().map(|r|{let add=r["action"]["addLabelIds"].as_array().cloned().unwrap_or_default();let remove=r["action"]["removeLabelIds"].as_array().cloned().unwrap_or_default();let folder=add.iter().filter_map(Value::as_str).find(|s|!matches!(*s,"TRASH"|"STARRED"|"INBOX"));json!({"id":r["id"],"name":r["criteria"]["subject"].as_str().or(r["criteria"]["from"].as_str()).unwrap_or("Gmail filter"),"enabled":true,"editable":false,"conditions":{"from":r["criteria"]["from"],"to":r["criteria"]["to"],"subject":r["criteria"]["subject"],"contains":r["criteria"]["query"],"hasAttachment":r["criteria"]["hasAttachment"]},"actions":{"folder":folder.map(|id|format!("custom:{id}")),"markRead":remove.contains(&json!("UNREAD")),"star":add.contains(&json!("STARRED")),"trash":add.contains(&json!("TRASH"))}})}).collect::<Vec<_>>();return Ok(json!({"scope":"provider","items":items,"notice":"Gmail filters run on the server. Existing complex filters are listed read-only to avoid dropping unsupported criteria; create a new filter or delete one explicitly."}))}if a.provider=="outlook"{let v=state.api(&a,"GET",&format!("{MS}/mailFolders/inbox/messageRules"),Value::Null).await?;let items=v["value"].as_array().unwrap_or(&vec![]).iter().map(|r|json!({"id":r["id"],"name":r["displayName"],"enabled":r["isEnabled"],"editable":false,"conditions":{"from":r["conditions"]["senderContains"].as_array().and_then(|v|v.first()).and_then(Value::as_str),"to":r["conditions"]["recipientContains"].as_array().and_then(|v|v.first()).and_then(Value::as_str),"subject":r["conditions"]["subjectContains"].as_array().and_then(|v|v.first()).and_then(Value::as_str),"contains":r["conditions"]["bodyContains"].as_array().and_then(|v|v.first()).and_then(Value::as_str),"hasAttachment":r["conditions"]["hasAttachments"]},"actions":{"folder":r["actions"]["moveToFolder"].as_str().map(|id|format!("custom:{id}")),"markRead":r["actions"]["markAsRead"],"trash":r["actions"]["delete"]}})).collect::<Vec<_>>();return Ok(json!({"scope":"provider","items":items,"notice":"Server-side Microsoft inbox rules. Complex existing rules are read-only here; create a replacement explicitly rather than losing unsupported actions."}))}Err("This account does not support inbox rules.".into())}
#[tauri::command]
pub async fn mail_rule_save(window:tauri::WebviewWindow,state:tauri::State<'_,Arc<App>>,store:tauri::State<'_,Arc<MailStore>>,account:String,rule:Value)->Result<Value>{crate::windows::check_owner(&state,window.label(),&account)?;validate_rule(&rule)?;let a=state.account(&account).await?;if let Some(settings)=&a.exchange{return crate::exchange::rule_save(settings.clone(),exchange_credentials(&a)?,rule,false).await}if a.provider=="imap"{return store.save_rule(&account,&rule)}if rule["id"].as_str().is_some_and(|id|!id.is_empty()){return Err("Existing server rules are read-only to preserve criteria Yas Mail does not edit. Create a new rule, review it, then explicitly delete the old one.".into())}if a.provider=="gmail"{return state.api(&a,"POST",&format!("{GM}/settings/filters"),google_rule(&rule)?).await}if a.provider=="outlook"{return state.api(&a,"POST",&format!("{MS}/mailFolders/inbox/messageRules"),microsoft_rule(&rule)?).await}Err("This account does not support inbox rules.".into())}
#[tauri::command]
pub async fn mail_rule_delete(window:tauri::WebviewWindow,state:tauri::State<'_,Arc<App>>,store:tauri::State<'_,Arc<MailStore>>,account:String,id:String)->Result<Value>{crate::windows::check_owner(&state,window.label(),&account)?;let a=state.account(&account).await?;if let Some(settings)=&a.exchange{return crate::exchange::rule_save(settings.clone(),exchange_credentials(&a)?,json!({"id":id}),true).await}if a.provider=="imap"{store.delete_rule(&account,&id)?;return Ok(json!({"ok":true}))}let path=match a.provider.as_str(){"gmail"=>format!("{GM}/settings/filters/{}",crate::segment(&id)),"outlook"=>format!("{MS}/mailFolders/inbox/messageRules/{}",crate::segment(&id)),_=>return Err("This account does not support inbox rules.".into())};state.api(&a,"DELETE",&path,Value::Null).await}

#[cfg(test)]
mod tests{
use super::*;
fn rule()->Value{json!({"name":"Invoices","enabled":true,"conditions":{"from":"billing@example.com","subject":"Invoice","hasAttachment":true},"actions":{"markRead":true,"folder":"custom:Label_123"}})}
#[test]fn providers_receive_real_rule_conditions_and_actions(){let g=google_rule(&rule()).unwrap();assert_eq!(g["criteria"]["hasAttachment"],true);assert!(g["action"]["addLabelIds"].as_array().unwrap().contains(&json!("Label_123")));assert!(g["action"]["removeLabelIds"].as_array().unwrap().contains(&json!("UNREAD")));let m=microsoft_rule(&rule()).unwrap();assert_eq!(m["conditions"]["senderContains"][0],"billing@example.com");assert_eq!(m["actions"]["moveToFolder"],"Label_123");assert_eq!(m["actions"]["markAsRead"],true);}
#[test]fn broad_rules_and_unsupported_actions_are_rejected(){assert!(validate_rule(&json!({"name":"Everything","conditions":{},"actions":{"trash":true}})).is_err());let mut r=rule();r["actions"]["star"]=json!(true);assert!(microsoft_rule(&r).is_err());r["enabled"]=json!(false);assert!(google_rule(&r).is_err());}
#[test]fn local_rules_require_every_condition_and_attachment_state(){let r=rule();assert!(rule_matches(&r,&json!({"from":"Billing <billing@example.com>","subject":"Invoice 123","attachments":[{"id":"a"}]})));assert!(!rule_matches(&r,&json!({"from":"other@example.com","subject":"Invoice","attachments":[{}]})));assert!(!rule_matches(&r,&json!({"from":"billing@example.com","subject":"Invoice","attachments":[]})));}
#[test]fn imap_mailbox_ids_and_unicode_names_round_trip(){for folder in ["Projects/Client A","السفر","A & B","收件箱"]{assert_eq!(imap_folder(&imap_id(folder)).unwrap(),folder);assert_eq!(utf7_decode(&utf7_encode(folder)),folder);}assert!(imap_folder("custom:../bad").is_err());assert!(name("bad\r\nname").is_err());}
}
